// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.packed;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.function.ToDoubleFunction;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.query.algebra.Filter;
import org.eclipse.rdf4j.query.algebra.Join;
import org.eclipse.rdf4j.query.algebra.StatementPattern;
import org.eclipse.rdf4j.query.algebra.TupleExpr;
import org.eclipse.rdf4j.query.algebra.ValueConstant;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.algebra.evaluation.optimizer.cascades.OptimizationGoal;
import org.junit.jupiter.api.Test;

/**
 * Branch-and-bound pruning and winner selection assume that the scalar objective a provider projects from a cost vector
 * is a finite, non-negative cost. A provider that returns a negative or non-finite objective must be treated as an
 * unknown (saturated) cost at the session boundary instead of making a plan look cheaper than free or failing the whole
 * planning run.
 */
class PackedObjectiveScoreContractTest {

	@Test
	void negativeProviderObjectiveIsAnUnknownCostAtTheSessionBoundary() {
		PackedCostSession session = new EventSourcingPackedCostSession(objectiveSession(estimate -> -50.0d));
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setRows(10.0d, 10.0d);

		assertEquals(Double.MAX_VALUE, session.objectiveScore(estimate),
				"a negative objective is not a cost; it must be treated as unknown");
	}

	@Test
	void nonFiniteProviderObjectiveIsAnUnknownCostAtTheSessionBoundary() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setRows(10.0d, 10.0d);

		assertEquals(Double.MAX_VALUE,
				new EventSourcingPackedCostSession(objectiveSession(e -> Double.NaN)).objectiveScore(estimate));
		assertEquals(Double.MAX_VALUE,
				new EventSourcingPackedCostSession(objectiveSession(e -> Double.POSITIVE_INFINITY))
						.objectiveScore(estimate));
	}

	@Test
	void validProviderObjectiveIsPassedThroughUnchanged() {
		PackedCostEstimate estimate = new PackedCostEstimate();
		estimate.setRows(10.0d, 10.0d);

		assertEquals(42.0d,
				new EventSourcingPackedCostSession(objectiveSession(e -> 42.0d)).objectiveScore(estimate));
		assertEquals(0.0d,
				new EventSourcingPackedCostSession(objectiveSession(e -> 0.0d)).objectiveScore(estimate));
	}

	@Test
	void negativeProviderObjectiveMustNotProduceANegativePlanCost() {
		PackedPlanningResult result = PackedCascadesPlanner.optimize(filteredPattern(), OptimizationGoal.root(),
				objectiveModel(estimate -> -50.0d));

		assertTrue(Double.isFinite(result.totalCost()) && result.totalCost() >= 0.0d,
				"a completed plan cannot cost less than nothing: total=" + result.totalCost());
	}

	@Test
	void negativeProviderObjectiveMustNotProduceANegativeJoinPlanCost() {
		PackedPlanningResult result = PackedCascadesPlanner.optimize(chain(), OptimizationGoal.root(),
				objectiveModel(estimate -> estimate.workRows() >= 1000.0d ? -1.0e6d : estimate.workRows()));

		assertTrue(Double.isFinite(result.totalCost()) && result.totalCost() >= 0.0d,
				"a join plan cannot cost less than nothing: total=" + result.totalCost());
	}

	@Test
	void nanProviderObjectiveMustNotFailPlanning() {
		PackedPlanningResult result = PackedCascadesPlanner.optimize(filteredPattern(), OptimizationGoal.root(),
				objectiveModel(estimate -> Double.NaN));

		assertTrue(Double.isFinite(result.totalCost()) && result.totalCost() >= 0.0d,
				"an unknown objective must plan with a finite saturated cost: total=" + result.totalCost());
	}

	private static TupleExpr filteredPattern() {
		return new Filter(new StatementPattern(Var.of("subject"), Var.of("predicate"), Var.of("object")),
				new ValueConstant(SimpleValueFactory.getInstance().createLiteral(true)));
	}

	private static TupleExpr chain() {
		SimpleValueFactory values = SimpleValueFactory.getInstance();
		StatementPattern first = new StatementPattern(Var.of("s"), Var.of("p1", values.createIRI("urn:small")),
				Var.of("x"));
		StatementPattern second = new StatementPattern(Var.of("x"), Var.of("p2", values.createIRI("urn:large")),
				Var.of("y"));
		return new Join(first, second);
	}

	private static PackedCostSession objectiveSession(ToDoubleFunction<PackedCostEstimate> objective) {
		return new PackedCostSession() {

			@Override
			public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
			}

			@Override
			public double objectiveScore(PackedCostEstimate estimate) {
				return objective.applyAsDouble(estimate);
			}
		};
	}

	private static PackedCostModel objectiveModel(ToDoubleFunction<PackedCostEstimate> objective) {
		return new PackedCostModel() {

			@Override
			public double estimateRows(PackedQueryView query, int relationId) {
				return Double.NaN;
			}

			@Override
			public PackedCostSession openSession(PackedQueryView query) {
				return new PackedCostSession() {

					@Override
					public void estimateLeaf(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (!query.isStatementPattern(relationId)) {
							return;
						}
						double rows = query.materializeRelation(relationId).toString().contains("urn:large")
								? 1000.0d
								: 10.0d;
						output.setRows(rows, rows);
						output.setInclusivePhysicalCost(rows, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
					}

					@Override
					public void appendFactor(int relationId, PackedCostContext context, PackedCostEstimate output) {
						estimateLeaf(relationId, context, output);
					}

					@Override
					public void refineOperator(int relationId, PackedCostContext context, PackedCostEstimate output) {
						if (query.isFilter(relationId)) {
							output.setLocalPhysicalCost(1.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d, 0.0d);
						}
					}

					@Override
					public double objectiveScore(PackedCostEstimate estimate) {
						return objective.applyAsDouble(estimate);
					}
				};
			}
		};
	}
}
